const input = $input.first().json;
const clean = (value) => value == null ? null : String(value).replace(/\s+/g, ' ').trim();
const lower = (value) => clean(value)?.toLocaleLowerCase('fr-FR') || null;
const validDate = (value) => { const cleaned = clean(value); if (!cleaned) return null; const d = new Date(cleaned); return Number.isNaN(d.getTime()) ? null : d.toISOString(); };
const rows = (input.raw_rows || []).map((row, index) => {
  const payload = row.payload || {};
  const sourceOfferId = clean(payload.id || row.source_offer_id);
  const title = clean(payload.intitule || payload.title);
  const description = clean(payload.description);
  const company = clean(payload.entreprise?.nom || payload.company_name);
  const city = clean(payload.lieuTravail?.libelle || payload.location?.city);
  const postalCode = clean(payload.lieuTravail?.codePostal || payload.location?.postal_code);
  const contractCode = clean(payload.typeContrat || payload.contract_type);
  const publishedAt = validDate(payload.dateCreation || payload.published_at);
  const reasons = [];
  if (!sourceOfferId) reasons.push(input.reason_codes.missing_source_offer_id);
  if (!title) reasons.push(input.reason_codes.missing_title);
  if (!description) reasons.push(input.reason_codes.empty_description);
  if (!company) reasons.push(input.reason_codes.missing_company);
  if ((payload.dateCreation || payload.published_at) && !publishedAt) reasons.push(input.reason_codes.invalid_date);
  if (!city && !postalCode) reasons.push(input.reason_codes.missing_location);
  if (contractCode && !input.contract_map[contractCode]) reasons.push(input.reason_codes.unknown_contract);
  const rejected = reasons.includes(input.reason_codes.missing_source_offer_id) || reasons.includes(input.reason_codes.missing_title);
  const status = rejected ? 'rejected' : reasons.length ? 'needs_review' : 'valid';
  const quality = { has_title: Boolean(title), has_description: Boolean(description), has_company: Boolean(company), has_location: Boolean(city || postalCode), has_valid_date: Boolean(publishedAt), has_known_contract: Boolean(!contractCode || input.contract_map[contractCode]) };
  return { offer_key: sourceOfferId ? `${input.source}:${sourceOfferId}` : `${input.source}:missing-${index}`, raw_offer_key: row.raw_offer_key || null, source: input.source, source_offer_id: sourceOfferId, title: title || '', normalized_title: lower(title) || '', description_excerpt: description ? description.slice(0, 500) : null, job_family: null, contract_type: input.contract_map[contractCode] || contractCode || null, declared_positions: Number.isFinite(Number(payload.nombrePostes)) ? Number(payload.nombrePostes) : null, location_label: city, postal_code: postalCode, city, location_country: 'FR', declared_company_name: company, published_at: publishedAt, normalize_version: input.normalize_version, normalization_status: status, normalization_reasons_json: JSON.stringify(reasons), quality_json: JSON.stringify(quality), status: rejected ? 'rejected' : 'active', updated_at: new Date().toISOString() };
});
return [{ json: { ...input, job_offer_upserts: rows, quality_report: { total: rows.length, valid: rows.filter(r => r.normalization_status === 'valid').length, needs_review: rows.filter(r => r.normalization_status === 'needs_review').length, rejected: rows.filter(r => r.normalization_status === 'rejected').length } } }];
